_ANDROID_JSON = '    fun jsonParse(s: Any?): Any? = jsonToEpl(org.json.JSONTokener(s as String).nextValue())\n    private fun jsonToEpl(v: Any?): Any? = when (v) {\n        is org.json.JSONObject -> {\n            val m = LinkedHashMap<String, Any?>()\n            for (k in v.keys()) m[k] = jsonToEpl(v.get(k))\n            m\n        }\n        is org.json.JSONArray -> {\n            val l = ArrayList<Any?>()\n            for (i in 0 until v.length()) l.add(jsonToEpl(v.get(i)))\n            l\n        }\n        org.json.JSONObject.NULL -> null\n        else -> v\n    }\n    fun jsonStringify(v: Any?): String = eplToJson(v).toString()\n    private fun eplToJson(v: Any?): Any? = when (v) {\n        is Map<*, *> -> {\n            val o = org.json.JSONObject()\n            for ((k, vv) in v) o.put(k.toString(), eplToJson(vv))\n            o\n        }\n        is List<*> -> {\n            val a = org.json.JSONArray()\n            for (it in v) a.put(eplToJson(it))\n            a\n        }\n        null -> org.json.JSONObject.NULL\n        else -> v\n    }\n'

_ANDROID_BASE64 = '    fun base64Encode(text: String): String =\n        android.util.Base64.encodeToString(text.toByteArray(Charsets.UTF_8), android.util.Base64.NO_WRAP)\n    fun base64Decode(text: String): String =\n        String(android.util.Base64.decode(text, android.util.Base64.NO_WRAP), Charsets.UTF_8)'

_ANDROID_DB = '    // ─── SQLite bridge (db_* builtins) ───\n    fun dbOpen(name: String): android.database.sqlite.SQLiteDatabase {\n        val ctx = EPLApplication.instance.applicationContext\n        return ctx.openOrCreateDatabase(name, android.content.Context.MODE_PRIVATE, null)\n    }\n\n    fun dbExecute(db: Any?, sql: String, params: List<Any?> = emptyList<Any?>()) {\n        val database = db as android.database.sqlite.SQLiteDatabase\n        if (params.isEmpty()) database.execSQL(sql)\n        else database.execSQL(sql, params.toTypedArray())\n    }\n\n    fun dbQuery(\n        db: Any?,\n        sql: String,\n        params: List<Any?> = emptyList<Any?>(),\n    ): MutableList<Map<String, Any?>> {\n        val database = db as android.database.sqlite.SQLiteDatabase\n        val args = params.map { it?.toString() }.toTypedArray()\n        val rows = mutableListOf<Map<String, Any?>>()\n        database.rawQuery(sql, args).use { c ->\n            while (c.moveToNext()) {\n                val row = LinkedHashMap<String, Any?>()\n                for (i in 0 until c.columnCount) {\n                    row[c.getColumnName(i)] = when (c.getType(i)) {\n                        android.database.Cursor.FIELD_TYPE_INTEGER -> c.getLong(i)\n                        android.database.Cursor.FIELD_TYPE_FLOAT -> c.getDouble(i)\n                        android.database.Cursor.FIELD_TYPE_NULL -> null\n                        android.database.Cursor.FIELD_TYPE_BLOB -> c.getBlob(i)\n                        else -> c.getString(i)\n                    }\n                }\n                rows.add(row)\n            }\n        }\n        return rows\n    }\n\n    fun dbQueryOne(\n        db: Any?,\n        sql: String,\n        params: List<Any?> = emptyList<Any?>(),\n    ): Map<String, Any?>? = dbQuery(db, sql, params).firstOrNull()\n\n    fun dbCount(db: Any?, table: String): Long {\n        val rows = dbQuery(db, "SELECT count(*) AS c FROM " + table)\n        return (rows.firstOrNull()?.get("c") as? Number)?.toLong() ?: 0L\n    }\n\n    // Identifier + type validation mirrors the EPL interpreter (stdlib._db_create_table):\n    // raw SQL column defs are rejected and every name/type component is whitelisted,\n    // so a generated app is no more injection-prone than the interpreter.\n    private val DB_IDENT = Regex("^[a-zA-Z_][a-zA-Z0-9_]*$")\n    private val DB_SAFE_TYPE_WORDS = setOf(\n        "TEXT", "INTEGER", "REAL", "BLOB", "NUMERIC", "DECIMAL", "FLOAT", "DOUBLE",\n        "VARCHAR", "CHAR", "BOOLEAN", "DATE", "DATETIME", "TIMESTAMP", "PRIMARY",\n        "KEY", "NOT", "NULL", "UNIQUE", "AUTOINCREMENT", "DEFAULT", "CHECK", "REFERENCES",\n    )\n\n    fun dbCreateTable(db: Any?, table: String, columns: Any?): Boolean {\n        val database = db as android.database.sqlite.SQLiteDatabase\n        if (!DB_IDENT.matches(table)) throw RuntimeException("Invalid table name: " + table)\n        val cols = (columns as? Map<*, *>)\n            ?: throw RuntimeException("db_create_table requires a map of name -> type.")\n        val defs = StringBuilder()\n        for ((rawName, rawType) in cols) {\n            val name = rawName.toString()\n            if (!DB_IDENT.matches(name)) throw RuntimeException("Invalid column name: " + name)\n            val typ = rawType.toString()\n            for (w in typ.uppercase().split(Regex("\\\\s+"))) {\n                if (w.isEmpty()) continue\n                val paren = w.indexOf(\'(\')\n                if (paren >= 0) {\n                    val base = w.substring(0, paren)\n                    val rest = w.substring(paren + 1)\n                    if (base !in DB_SAFE_TYPE_WORDS || !rest.endsWith(")") ||\n                        !Regex("^\\\\d+(\\\\s*,\\\\s*\\\\d+)*$").matches(rest.dropLast(1))\n                    ) throw RuntimeException("Invalid column type component: " + w)\n                } else if (!w.all { it.isDigit() } && w !in DB_SAFE_TYPE_WORDS) {\n                    throw RuntimeException("Invalid column type component: " + w)\n                }\n            }\n            if (defs.isNotEmpty()) defs.append(", ")\n            defs.append("\\"").append(name).append("\\" ").append(typ)\n        }\n        database.execSQL("CREATE TABLE IF NOT EXISTS \\"" + table + "\\" (" + defs + ")")\n        return true\n    }\n\n    fun dbTables(db: Any?): MutableList<String> {\n        val database = db as android.database.sqlite.SQLiteDatabase\n        val out = mutableListOf<String>()\n        database.rawQuery(\n            "SELECT name FROM sqlite_master WHERE type=\'table\' ORDER BY name", null,\n        ).use { c -> while (c.moveToNext()) out.add(c.getString(0)) }\n        return out\n    }\n\n    fun dbClose(db: Any?) {\n        (db as? android.database.sqlite.SQLiteDatabase)?.close()\n    }'

_ANDROID_FILE = '    // ─── Sandboxed file bridge (file_* builtins) ───\n    // Paths resolve inside the app\'s private filesDir; a bare name or relative path\n    // never escapes the sandbox, matching Android\'s per-app storage model.\n    private fun resolveFile(path: String): java.io.File {\n        val base = EPLApplication.instance.applicationContext.filesDir\n        val f = java.io.File(path)\n        return if (f.isAbsolute) f else java.io.File(base, path)\n    }\n\n    fun fileExists(path: String): Boolean = resolveFile(path).exists()\n    fun fileDelete(path: String): Boolean = resolveFile(path).let { if (it.exists()) it.delete() else false }\n    fun fileRead(path: String): String = resolveFile(path).readText()\n    fun fileWrite(path: String, content: Any?): Boolean {\n        resolveFile(path).writeText(content?.toString() ?: "")\n        return true\n    }\n    fun fileAppend(path: String, content: Any?): Boolean {\n        resolveFile(path).appendText(content?.toString() ?: "")\n        return true\n    }\n    fun fileSize(path: String): Long = resolveFile(path).let { if (it.exists()) it.length() else 0L }'

# ─── Console/JVM platform slots ───
_CONSOLE_JSON = '    fun jsonParse(s: Any?): Any? = JsonMini.parse(s as String)\n    fun jsonStringify(v: Any?): String = JsonMini.stringify(v)'

_CONSOLE_BASE64 = '    fun base64Encode(text: String): String =\n        java.util.Base64.getEncoder().encodeToString(text.toByteArray(Charsets.UTF_8))\n    fun base64Decode(text: String): String =\n        String(java.util.Base64.getDecoder().decode(text), Charsets.UTF_8)'

_CONSOLE_DB = '    // ─── SQLite bridge (db_* builtins) — unsupported on the console/JVM target ───\n    // The Android target backs these with android.database.sqlite; a bare JVM has no\n    // equivalent bundled. Fail loudly so db-backed EPL is caught, never silently wrong.\n    private fun noDb(): Nothing =\n        throw RuntimeException("Database builtins (db_*) are not supported on the console/JVM target; use the Android target or a server backend.")\n    fun dbOpen(name: String): Any? = noDb()\n    fun dbExecute(db: Any?, sql: String, params: List<Any?> = emptyList<Any?>()): Unit = noDb()\n    fun dbQuery(db: Any?, sql: String, params: List<Any?> = emptyList<Any?>()): MutableList<Map<String, Any?>> = noDb()\n    fun dbQueryOne(db: Any?, sql: String, params: List<Any?> = emptyList<Any?>()): Map<String, Any?>? = noDb()\n    fun dbCount(db: Any?, table: String): Long = noDb()\n    fun dbCreateTable(db: Any?, table: String, columns: Any?): Boolean = noDb()\n    fun dbTables(db: Any?): MutableList<String> = noDb()\n    fun dbClose(db: Any?): Unit = noDb()'

_CONSOLE_FILE = '    // ─── File bridge (file_* builtins) — resolves against the working directory ───\n    private fun resolveFile(path: String): java.io.File = java.io.File(path)\n\n    fun fileExists(path: String): Boolean = resolveFile(path).exists()\n    fun fileDelete(path: String): Boolean = resolveFile(path).let { if (it.exists()) it.delete() else false }\n    fun fileRead(path: String): String = resolveFile(path).readText()\n    fun fileWrite(path: String, content: Any?): Boolean {\n        resolveFile(path).writeText(content?.toString() ?: "")\n        return true\n    }\n    fun fileAppend(path: String, content: Any?): Boolean {\n        resolveFile(path).appendText(content?.toString() ?: "")\n        return true\n    }\n    fun fileSize(path: String): Long = resolveFile(path).let { if (it.exists()) it.length() else 0L }'

_CONSOLE_JSON_HELPER = '\n/** Minimal JSON reader/writer for the console target (no external deps). */\nobject JsonMini {\n    fun parse(s: String): Any? = Parser(s).parseValue()\n    private class Parser(val s: String) {\n        var i = 0\n        fun parseValue(): Any? {\n            skipWs()\n            return when (s[i]) {\n                \'{\' -> obj()\n                \'[\' -> arr()\n                \'"\' -> str()\n                \'t\' -> { expect("true"); true }\n                \'f\' -> { expect("false"); false }\n                \'n\' -> { expect("null"); null }\n                else -> num()\n            }\n        }\n        fun obj(): LinkedHashMap<String, Any?> {\n            val m = LinkedHashMap<String, Any?>(); i++; skipWs()\n            if (s[i] == \'}\') { i++; return m }\n            while (true) {\n                skipWs(); val k = str(); skipWs(); i++\n                m[k] = parseValue(); skipWs()\n                if (s[i] == \',\') { i++; continue }\n                i++; break\n            }\n            return m\n        }\n        fun arr(): ArrayList<Any?> {\n            val a = ArrayList<Any?>(); i++; skipWs()\n            if (s[i] == \']\') { i++; return a }\n            while (true) {\n                a.add(parseValue()); skipWs()\n                if (s[i] == \',\') { i++; continue }\n                i++; break\n            }\n            return a\n        }\n        fun str(): String {\n            val sb = StringBuilder(); i++\n            while (s[i] != \'"\') {\n                if (s[i] == \'\\\\\') {\n                    i++\n                    when (s[i]) {\n                        \'n\' -> sb.append(\'\\n\')\n                        \'t\' -> sb.append(\'\\t\')\n                        \'r\' -> sb.append(\'\\r\')\n                        \'b\' -> sb.append(\'\\b\')\n                        \'f\' -> sb.append(\'\\u000c\')\n                        \'/\' -> sb.append(\'/\')\n                        \'"\' -> sb.append(\'"\')\n                        \'\\\\\' -> sb.append(\'\\\\\')\n                        \'u\' -> { sb.append(s.substring(i + 1, i + 5).toInt(16).toChar()); i += 4 }\n                        else -> sb.append(s[i])\n                    }\n                } else sb.append(s[i])\n                i++\n            }\n            i++\n            return sb.toString()\n        }\n        fun num(): Any {\n            val start = i\n            while (i < s.length && (s[i].isDigit() || s[i] in "+-.eE")) i++\n            val t = s.substring(start, i)\n            return if (t.any { it in ".eE" }) t.toDouble()\n                   else t.toLong().let { if (it in Int.MIN_VALUE..Int.MAX_VALUE) it.toInt() else it }\n        }\n        fun expect(w: String) { require(s.regionMatches(i, w, 0, w.length)); i += w.length }\n        fun skipWs() { while (i < s.length && s[i].isWhitespace()) i++ }\n    }\n    fun stringify(v: Any?): String {\n        val sb = StringBuilder(); write(v, sb); return sb.toString()\n    }\n    private fun write(v: Any?, sb: StringBuilder) {\n        when (v) {\n            null -> sb.append("null")\n            is Boolean -> sb.append(v)\n            is Number -> sb.append(v.toString())\n            is CharSequence -> quote(v.toString(), sb)\n            is Map<*, *> -> {\n                sb.append(\'{\'); var first = true\n                for ((k, vv) in v) {\n                    if (!first) sb.append(", "); first = false\n                    quote(k.toString(), sb); sb.append(": "); write(vv, sb)\n                }\n                sb.append(\'}\')\n            }\n            is Collection<*> -> {\n                sb.append(\'[\'); var first = true\n                for (it in v) { if (!first) sb.append(", "); first = false; write(it, sb) }\n                sb.append(\']\')\n            }\n            else -> quote(v.toString(), sb)\n        }\n    }\n    private fun quote(s: String, sb: StringBuilder) {\n        sb.append(\'"\')\n        for (c in s) when (c) {\n            \'"\' -> sb.append("\\\\\\"")\n            \'\\\\\' -> sb.append("\\\\\\\\")\n            \'\\n\' -> sb.append("\\\\n")\n            \'\\r\' -> sb.append("\\\\r")\n            \'\\t\' -> sb.append("\\\\t")\n            else -> sb.append(c)\n        }\n        sb.append(\'"\')\n    }\n}\n'


def _assemble(package, json_r, base64_r, db_r, file_r):
    header = (
        f"package {package}\n\n"
        "/**\n"
        " * EPL Runtime Support for Android\n"
        " * Generated by EPL Kotlin Generator v2.0\n"
        " */\n"
        "object EPLRuntime {"
    )
    return "\n".join(
        [header, _CORE_1, json_r, _CORE_2A, base64_r, _CORE_2B, db_r, _MID, file_r, _FOOTER]
    )


def android_runtime(package):
    """Byte-identical to the historically verified Android EPLRuntime."""
    return _assemble(package, _ANDROID_JSON, _ANDROID_BASE64, _ANDROID_DB, _ANDROID_FILE)


def console_runtime(package):
    """EPLRuntime for the console/JVM target (plain-JVM slots + JsonMini helper)."""
    body = _assemble(package, _CONSOLE_JSON, _CONSOLE_BASE64, _CONSOLE_DB, _CONSOLE_FILE)
    return body + "\n" + _CONSOLE_JSON_HELPER
